 public static function key(string $source):string{return 'inventory_loan_'.substr(hash('sha256',$source),0,24);}
 public static function messages(string $locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$source=>$translation)$out[self::key($source)]=$en?$translation:$source;return$out;}
 public static function text(string $source,array $messages,array $values=[]):string{if(!isset($messages[self::key($source)]))return InventoryMoveMessages::text($source,$messages,$values);$replace=[];foreach($values as$name=>$value)$replace['{'.$name.'}']=(string)$value;return strtr($messages[self::key($source)],$replace);}
